import java.io.*;

public class Main {
    public static void main(String[] args) {
        // Unchecked: Compiler doesn't complain
        int[] arr = {1, 2};
        // System.out.println(arr[5]); // RuntimeException

        // Checked: Compiler forces handling
        // Thread.sleep(1000); // Compile Error!

        try {
            dangerousOperation();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    // 'throws' declares Checked Exception
    public static void dangerousOperation() throws InterruptedException {
        Thread.sleep(1000);
    }
}
